const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;

const SWORD_BASE_PREMIUM = 100;

const policyBasePremium = (items: Item[]): number =>
  items.length === 0 ? 0 : SWORD_BASE_PREMIUM;

const withFirstInsuranceSurcharge = (base: number): number =>
  base + (base * FIRST_INSURANCE_SURCHARGE_PERCENT) / 100;

const quotePremium = (items: Item[]): number =>
  withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE;

export const runScenario = (scenario: Scenario): { results: Result[] } => ({
  results: scenario.steps.map((step) =>
    step.op === "quote"
      ? { premium: quotePremium(step.items) }
      : { payout: 0, remainingCap: 0 },
  ),
});

